\label{qwoodin}
    Suppose that $\kappa$ is strongly compact and $\textsf{\textup{GCH}}$ holds
    below $\kappa$. Must $\textsf{\textup{GCH}}$ hold?

\label{thma}
    If $\kappa$ is a strongly compact cardinal and $\textsf{\textup{GCH}}$ holds below $\kappa$,
    then $\textsf{\textup{GCH}}$ holds.

\label{dfine}
    Suppose that $\kappa$ is an uncountable cardinal.
    \begin{enumerate}
        \item For any $\lambda\ge\kappa$, $\kappa$ is \emph{$\lambda$-strongly compact} iff there exists a definable elementary embedding $j:V\rightarrow M$ into a transitive class $M$ with critical point $\kappa$,
              such that there exists a $D\in M$ with $j[\lambda]\subseteq D$ and $M\models |D|<j(\kappa)$.
              In this case, we say that $D$ is \emph{minimal} iff $|C|^M\ge|D|^M$ for every $C\in M$ with $j[\lambda]\subseteq C$.
        \item We say that $\kappa$ is \emph{strongly compact} iff it is $\lambda$-strongly compact for every $\lambda\ge\kappa$.
    \end{enumerate}

\label{lpullback}
    Suppose $\kappa\leq \lambda$ are two uncountable cardinals
    and $\kappa$ is $\lambda$-strongly compact,
    as witnessed by a definable elementary embedding $j:V\rightarrow M$ and a minimal $D$. Let $d:=|D|^M$. Then:
    \begin{enumerate}
        \item[(1)] If $S\in M$ and $|S|^M< d$, then $|\{\alpha<\lambda\mathrel{|}\allowbreak j(\alpha)\in S\}|<\lambda$.
        \item[(2)] There is a set $R\subseteq d$ cofinal in $d$ with $|R|\le\lambda$.
    \end{enumerate}

\label{lcapacity}
    Suppose $\kappa\le\lambda$ are two uncountable cardinals
    and $\kappa$ is $\lambda$-strongly compact,
    as witnessed by a definable elementary embedding $j:V\rightarrow M$ and a minimal $D$.
    Put $d:=|D|^M$ and $F:=\{j(A)\cap D\mathrel{|}\allowbreak A\subseteq\lambda\}$.
    For every $T\in M$ with $|T|^M\le d$, we have
    \begin{equation}\label{eq1}
        |F \cap T|\le 2^{<\lambda}.
    \end{equation}

\label{cldelta}
        Suppose that $A,B\subseteq\lambda$ are distinct. Then
        $$\min\bigl((j(A)\cap D)\mathbin{\bigtriangleup}(j(B)\cap D)\bigr)=j\bigl(\min(A\mathbin{\bigtriangleup} B)\bigr).$$
